"""PDF116 printed 223–224: Example 6.17 (pain-relieving drugs, CI for p1−p2); Unit 6 key points."""
from class12_statistics_common import Builder, save

SOL = ('Solution:', 'حل:', 'حل:')
b = Builder()
b.h('Example 6.17', 'مثال 6.17', 'بېلګه 6.17')
b.p('Two pairs relieving drugs were compared each on independent samples of $n_1=1000$, $n_2=1000$ individuals. Out of these individuals 750 receiving drug-I and 800 receiving drug-II reported some pain relief. Construct a 90% confidence interval for the difference between population proportions.', 'درد کم کرنے والی دو دواؤں کا موازنہ $n_1=1000$، $n_2=1000$ افراد کے آزاد نمونوں پر کیا گیا۔ ان افراد میں سے دوا-I لینے والے 750 اور دوا-II لینے والے 800 نے درد میں کچھ کمی بتائی۔ آبادی کے تناسبوں کے فرق کے لیے 90% اعتماد کا وقفہ بنائیں۔', 'د درد کمولو دوه درمل د $n_1=1000$، $n_2=1000$ کسانو په خپلواکو نمونو پرتله شول. له دې کسانو څخه د درمل-I اخیستونکو 750 او د درمل-II اخیستونکو 800 د درد یو څه کمښت راپور کړ. د نفوسونو د تناسبونو د توپیر لپاره 90% د باور واټن جوړ کړئ.')
b.h(*SOL)
b.p('As $p_1,p_2$ (population proportions) are unknown, therefore 100(1−α)% confidence interval for $(p_1-p_2)$ is $(\\hat{p}_1-\\hat{p}_2)\\pm Z_{\\alpha/2}\\sqrt{\\frac{\\hat{p}_1\\hat{q}_1}{n_1}+\\frac{\\hat{p}_2\\hat{q}_2}{n_2}}$', 'چونکہ $p_1,p_2$ (آبادی کے تناسب) نامعلوم ہیں، لہٰذا $(p_1-p_2)$ کے لیے 100(1−α)% اعتماد کا وقفہ $(\\hat{p}_1-\\hat{p}_2)\\pm Z_{\\alpha/2}\\sqrt{\\frac{\\hat{p}_1\\hat{q}_1}{n_1}+\\frac{\\hat{p}_2\\hat{q}_2}{n_2}}$ ہے', 'څرنګه چې $p_1,p_2$ (د نفوس تناسبونه) نامعلوم دي، نو د $(p_1-p_2)$ لپاره 100(1−α)% د باور واټن $(\\hat{p}_1-\\hat{p}_2)\\pm Z_{\\alpha/2}\\sqrt{\\frac{\\hat{p}_1\\hat{q}_1}{n_1}+\\frac{\\hat{p}_2\\hat{q}_2}{n_2}}$ دی')
b.p('Given information are;', 'دی گئی معلومات یہ ہیں؛', 'ورکړل شوي معلومات دا دي؛')
b.mlines([r'n_1=1000,\ X_1=750,\ \hat{p}_1=\frac{X_1}{n_1}=\frac{750}{1000}=0.75', r'\hat{q}_1=1-\hat{p}_1=1-0.75=0.25,', r'n_2=1000,\ X_2=800,\ \hat{p}_2=\frac{X_2}{n_2}=\frac{800}{100}=0.80', r'\hat{q}_2=1-\hat{p}_2=1-0.80=0.20,', r'1-\alpha=0.90,\ \alpha=0.10,\ \frac{\alpha}{2}=0.05.'])
b.p('From the area table of standard normal distribution, we have $Z_{\\alpha/2}=Z_{0.05}=1.645$.', 'معیاری نارمل تقسیم کے رقبے کے جدول سے ہمارے پاس $Z_{\\alpha/2}=Z_{0.05}=1.645$ ہے۔', 'د معیاري نورمال وېش د مساحت له جدول څخه لرو $Z_{\\alpha/2}=Z_{0.05}=1.645$.')
b.p('Hence, the 90% confidence interval for $(p_1-p_2)$ is', 'لہٰذا $(p_1-p_2)$ کے لیے 90% اعتماد کا وقفہ یہ ہے', 'نو د $(p_1-p_2)$ لپاره 90% د باور واټن دا دی')
b.mlines([r'(0.75-0.80)\pm 1.645\sqrt{\frac{(0.75)(0.25)}{1000}+\frac{(0.80)(0.20)}{1000}}', r'-0.05\pm 0.03', r'(-0.08,\ -0.02)'])
ex = b.build('stat12-p116-example-6-17', 'Example 6.17 — CI for the difference of two proportions', 'مثال 6.17 — دو تناسبوں کے فرق کا اعتماد کا وقفہ', 'بېلګه 6.17 — د دوو تناسبونو د توپیر د باور واټن', 116, [223])
issues = [{'id': 'stat12-p223-pairs-800-100', 'unit': 6, 'printedPage': 223, 'description': 'Example 6.17 prints “Two pairs relieving drugs” (for pain-relieving) and p̂₂ = 800/100 (should be 800/1000; result 0.80 is correct). Printed text retained.'}]

k = Builder()
k.h('Key points', 'اہم نکات', 'مهم ټکي')
k.group('list', [
    ('Statistical inference is a process of drawing conclusions (inferences) about the population on the basis of sample information from that population.', 'شماریاتی استنباط آبادی کی نمونہ جاتی معلومات کی بنیاد پر اس آبادی کے بارے میں نتائج (استنباط) اخذ کرنے کا عمل ہے۔', 'احصاییوي استنتاج د نفوس د نمونوي معلوماتو پر بنسټ د هغه نفوس په اړه د پایلو (استنتاجونو) د اخیستلو بهیر دی.'),
    ('Statistical estimation is a process by which the unknown value of a parameter is obtained from the sample observations.', 'شماریاتی تخمین وہ عمل ہے جس سے نمونے کے مشاہدات سے کسی پیرامیٹر کی نامعلوم قیمت حاصل کی جاتی ہے۔', 'احصاییوي اټکل هغه بهیر دی چې پکې د یوه پارامټر نامعلوم قیمت له نمونوي مشاهدو څخه ترلاسه کېږي.'),
    ('When a specific value is obtained from sample observations and is used to estimate the unknown value of the parameter, the process is called point estimation.', 'جب نمونے کے مشاہدات سے ایک مخصوص قیمت حاصل کر کے پیرامیٹر کی نامعلوم قیمت کے تخمین کے لیے استعمال کی جائے تو اس عمل کو نقطہ تخمین کہتے ہیں۔', 'کله چې له نمونوي مشاهدو څخه یو ټاکلی قیمت ترلاسه او د پارامټر د نامعلوم قیمت د اټکل لپاره وکارول شي، دې بهیر ته ټکي‌ییز اټکل وایي.'),
    ('When a range of values is obtained from sample observations within which the unknown value of parameter is believed to lie, the process is called interval estimation.', 'جب نمونے کے مشاہدات سے قیمتوں کی ایسی حد حاصل کی جائے جس کے اندر پیرامیٹر کی نامعلوم قیمت ہونے کا یقین ہو تو اس عمل کو وقفہ تخمین کہتے ہیں۔', 'کله چې له نمونوي مشاهدو څخه د قیمتونو داسې حد ترلاسه شي چې باور کېږي د پارامټر نامعلوم قیمت پکې پروت دی، دې بهیر ته واټني اټکل وایي.'),
    ('A rule, usually expressed as a formula that tells us how to calculate an estimate from the sample data is called an estimator and the resulting number is called an estimate.', 'وہ قاعدہ، جو عموماً فارمولا ہو اور بتائے کہ نمونے کے مواد سے تخمینہ کیسے معلوم کیا جائے، تخمین کار کہلاتا ہے اور حاصل عدد کو تخمینہ کہتے ہیں۔', 'هغه قاعده، چې معمولاً فورمول وي او ښيي چې له نمونوي معلوماتو څخه اټکل څنګه محاسبه شي، اټکلوونکی بلل کېږي او لاسته راغلي عدد ته اټکل وایي.'),
    ('An estimator is said to be unbiased if the mean of its sampling distribution is equal to the true value of the parameter, otherwise the estimator is said to be biased', 'تخمین کار غیر جانبدار کہلاتا ہے اگر اس کی نمونہ جاتی تقسیم کا اوسط پیرامیٹر کی حقیقی قیمت کے برابر ہو، ورنہ تخمین کار جانبدار کہلاتا ہے', 'اټکلوونکی بې‌پلوه بلل کېږي که د نمونوي وېش منځنی یې د پارامټر له رښتیني قیمت سره برابر وي، که نه اټکلوونکی پلوي بلل کېږي'),
    ('If $\\hat{\\theta}_1$ and $\\hat{\\theta}_2$ are two unbiased estimators of the same parameter θ and $Var(\\hat{\\theta}_1)<Var(\\hat{\\theta}_2)$ then $\\hat{\\theta}_1$ is called efficient estimator than $\\hat{\\theta}_2$.', 'اگر $\\hat{\\theta}_1$ اور $\\hat{\\theta}_2$ ایک ہی پیرامیٹر θ کے دو غیر جانبدار تخمین کار ہوں اور $Var(\\hat{\\theta}_1)<Var(\\hat{\\theta}_2)$ ہو تو $\\hat{\\theta}_1$ کو $\\hat{\\theta}_2$ سے زیادہ مؤثر تخمین کار کہتے ہیں۔', 'که $\\hat{\\theta}_1$ او $\\hat{\\theta}_2$ د یوه پارامټر θ دوه بې‌پلوه اټکلوونکي وي او $Var(\\hat{\\theta}_1)<Var(\\hat{\\theta}_2)$ وي، نو $\\hat{\\theta}_1$ تر $\\hat{\\theta}_2$ موثر اټکلوونکی بلل کېږي.'),
    ('An estimator which is linear, unbiased and has minimum variances among a group of linear unbiased estimators is called best linear unbiased estimator or BLUE.', 'وہ تخمین کار جو خطی، غیر جانبدار ہو اور خطی غیر جانبدار تخمین کاروں کے گروہ میں کم سے کم تغیر رکھتا ہو، بہترین خطی غیر جانبدار تخمین کار یا BLUE کہلاتا ہے۔', 'هغه اټکلوونکی چې خطي، بې‌پلوه وي او د خطي بې‌پلوه اټکلوونکو په ډله کې لږ تر لږه واریانس ولري، غوره خطي بې‌پلوه اټکلوونکی یا BLUE بلل کېږي.'),
    ('A rule for calculating two numbers to create an interval which has a high probability of containing the parameter of interest is the confidence interval.', 'دو اعداد معلوم کرنے کا وہ قاعدہ جس سے ایسا وقفہ بنے جس میں مطلوبہ پیرامیٹر کے شامل ہونے کا احتمال زیادہ ہو، اعتماد کا وقفہ ہے۔', 'د دوو عددونو د محاسبې هغه قاعده چې داسې واټن جوړ کړي چې د غوښتل شوي پارامټر د لرلو لوړ احتمال ولري، د باور واټن دی.'),
    ('The region between L and U is called confidence interval or confidence region or acceptance region for the unknown parameter θ.', 'L اور U کے درمیان علاقے کو نامعلوم پیرامیٹر θ کا اعتماد کا وقفہ یا اعتماد کا علاقہ یا قبولیت کا علاقہ کہتے ہیں۔', 'د L او U ترمنځ سیمې ته د نامعلوم پارامټر θ لپاره د باور واټن یا د باور سیمه یا د منلو سیمه وایي.'),
    ('The region beyond the acceptance region i.e. from −∞ to L and U to ∞ is known as critical region or rejection region.', 'قبولیت کے علاقے سے باہر کا علاقہ یعنی −∞ سے L اور U سے ∞ تک فیصلہ کن علاقہ یا رد کا علاقہ کہلاتا ہے۔', 'د منلو له سیمې بهر سیمه یعنې له −∞ څخه تر L او له U څخه تر ∞ پورې، بحراني سیمه یا د ردولو سیمه بلل کېږي.'),
    ('The probability that parameter lies in the rejection region is called significant level and is denoted by α.', 'پیرامیٹر کے رد کے علاقے میں ہونے کے احتمال کو معنویت کی سطح کہتے ہیں اور اسے α سے ظاہر کرتے ہیں۔', 'هغه احتمال چې پارامټر د ردولو په سیمه کې پروت وي، د معنی‌داریت کچه بلل کېږي او په α ښودل کېږي.'),
])
keys = k.build('stat12-u6-key-points', 'Unit 6 — Key points', 'یونٹ 6 — اہم نکات', 'واحد 6 — مهم ټکي', 116, [224])

if __name__ == '__main__':
    save(116, [(6, ex), (6, keys)], issues=issues)
